val OP_CHECK_FOR_HACKING = Opcode(
    code = 0xF8B6,
    mnemonic = "check_for_hacking",
    doc = "Returns a bitmask of 5 different types of detectable hacking. This opcode only works on DCv2 - it crashes on all other versions, since it tries to access memory at 8C007220, which is only a valid address on DC. The bits are: 0x01 = any byte in [8C007220, 8C0072E0) is nonzero (crashes on non-DC) 0x02 = has cheat device save files on VMU (always zero on non-DC); looks for names: CDX_CODES_00, CDX_SETTINGS, XT-CHEATS, FCDCHEATS 0x04 = any of the first 3 VMU-like devices (with function_code & 0x0E not equal to zero) on any of the 4 Maple buses reports power usage (standby or max) above 4 amps; always zero on non-DC systems 0x08 = hacked item flag has been set (see implementation of are_rare_drops_allowed in ItemCreator.cc) 0x10 = any bits in validation_flags in the character file are set (see PSOGCCharacterFile::Character)",
    params = listOf(
        Param(RegType(listOf(
            Param(IntType, null, null, false, true),
        )), null, null, false, false),
    ),
    stack = null,
    varargs = false,
    known = true,
    versionMask = 0xFF,
    argsMode = ArgsMode.Inline,
)
