private val OPCODES_FOR: MutableMap<Version, OpcodeTables> = mutableMapOf()

fun opcodesFor(version: Version): OpcodeTables = OPCODES_FOR.getOrPut(version) {
    val byCode = arrayOfNulls<Opcode>(256)
    val byCodeF8 = arrayOfNulls<Opcode>(256)
    val byCodeF9 = arrayOfNulls<Opcode>(256)
    val bit = version.bit
    for (op in ALL_OPCODES) {
        if (op.versionMask and bit == 0) continue
        val idx = op.code and 0xFF
        val target = when {
            op.code <= 0xFF -> byCode
            op.code <= 0xF8FF -> byCodeF8
            else -> byCodeF9
        }
        check(target[idx] == null) {
            "duplicate (version=$version, code=0x${op.code.toString(16)}) for ${op.mnemonic}"
        }
        target[idx] = op
    }
    OpcodeTables(byCode, byCodeF8, byCodeF9)
}
